  (() => {
    const perBookId = $json.orderId || $json.manifest?.order?.orderId;
    const rootGroupId = $json.rootOrderId || $json.root_order_id || $json.amazonOrderId || $json.manifest?.order?.rootOrderId || $json.manifest?.order?.amazonOrderId || $json.product_info?._root_order_id;
    if (!perBookId) throw new Error('orderId (per-book) is required');

    // Use merged review_stages from Fetch and Merge Review Stages (3) node
    const reviewStages = $json.mergedReviewStages || {
      postPdf: { status: 'in-review' },
    };

    const manifestKey = $json.manifestKey || `book-mvp-simple-adventure/orders/${perBookId}/manifests/3-manifest.json`;
    const backendUrl = $json.backendUrl || 'https://admin.littleherolabs.com';
    const manifestUrl = $json.manifestUrl || `${backendUrl}/api/manifests/${manifestKey}`;

    return {
      orderId: perBookId,
      root_order_id: rootGroupId || perBookId,
      amazon_order_id: rootGroupId || perBookId,

      // 3 manifest URL
      manifest_3_url: manifestUrl,

      // Overall status for post-Pdf stage (matches OrderStatus enum)
      // Review is ALWAYS needed after W3, so always set to pending_assembly_review
      status: 'pending_assembly_review',

      // Review stages with merged data (preserves preBria and postBria)
      review_stages: reviewStages,

      // Always set next_workflow to '4' after W3 completes
      // Review happens in UI, then approval triggers workflow 4 (not via router)
      next_workflow: '4',

      // W3 is done — mark execution finished so health monitor doesn't flag as stuck
      execution_status: 'done',
      started_at: null,
      current_workflow: null,

      workflow_step: 'book_assembly_completed',
      updated_at: new Date().toISOString(),
    };
  })()
}}

