  const pageNumberFromFilename = filenameToPageNumber(binMeta.fileName || current.pageImageFilename || metaFileName);
  const pageNumber =
    Number.isFinite(Number(current.pageNumber)) ? Number(current.pageNumber) :
    pageNumberFromPayload !== null ? pageNumberFromPayload :
    pageNumberFromFilename !== null ? pageNumberFromFilename :
    index;

  const fallbackName = `p${String(pageNumber).padStart(2, '0')}.png`;
  const fileName =
    current.pageImageFilename ||
    metaFileName ||
    binMeta.fileName ||
    fallbackName;

  let pageImageR2Key =
    current.pageImageR2Key ||
