  const overlays = order.overlayImages || order.overlays || {};
  if (Array.isArray(overlays)) {
    const hit = overlays.find(o => Number(o.pageNumber) === Number(TARGET_PAGE) && (o.imagePath || o.url || o.publicUrl || o.r2Key));
    if (hit) return withBust(toAbsoluteAsset(firstStr(hit.imagePath, hit.url, hit.publicUrl, hit.r2Key)));
  } else if (overlays && typeof overlays === 'object') {
    const re = TARGET_PAGE === 5 ? /animal|trail|footprint|p05|page.?5/i
            : TARGET_PAGE === 12 ? /sparkle|glow|p12|page.?12/i
            : null;
    if (re) {
      const cand = deepFindUrl(overlays, re);
      if (cand) return withBust(toAbsoluteAsset(cand));
    }
  }
  if (TARGET_PAGE === 5) {
    return withBust(`${backendUrl}/api/assets/book-mvp-simple-adventure/overlays/footprints/footprints.png`);
