/**
 * Normalize the repo-owned W3 assembly input response from the internal HTTP call.
 * n8n Cloud can surface the HTTP node output as a stream-like object even when
 * the request node is configured for JSON output.
 */
function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function toBufferLike(value) {
  if (!value) return null;
  if (Buffer.isBuffer(value)) return value;
  if (typeof value === 'string') return Buffer.from(value, 'utf8');
  if (Array.isArray(value)) return Buffer.from(value);

  const record = asObject(value);
  if (record.type === 'Buffer' && Array.isArray(record.data)) return Buffer.from(record.data);
  if (Array.isArray(record.data)) return Buffer.from(record.data);
  return null;
}

function extractStreamText(value) {
  const source = asObject(value);
  const directOutBuffer = toBufferLike(source._outBuffer);
  const outOffset = typeof source._outOffset === 'number' ? source._outOffset : null;
  if (directOutBuffer && directOutBuffer.length > 0) {
    const end = outOffset !== null && outOffset >= 0
      ? Math.min(outOffset, directOutBuffer.length)
      : directOutBuffer.length;
    const text = directOutBuffer.subarray(0, end).toString('utf8');
    if (text) return text;
  }

  const readableState = asObject(source._readableState);
  const chunks = [];
  const pushChunk = (chunk) => {
    const buffer = toBufferLike(chunk);
    if (buffer && buffer.length > 0) chunks.push(buffer);
  };

  const bufferState = readableState.buffer;
  if (Array.isArray(bufferState)) {
    for (const entry of bufferState) {
      const record = asObject(entry);
      pushChunk(entry);
      pushChunk(record.data);
      pushChunk(record.chunk);
    }
  } else {
    const bufferList = asObject(bufferState);
    let current = bufferList.head || null;
    let guard = 0;
    while (current && guard < 10000) {
      const record = asObject(current);
      pushChunk(record.data);
      pushChunk(record.chunk);
      current = record.next || null;
      guard += 1;
    }
  }

  if (!chunks.length) return null;
  return Buffer.concat(chunks).toString('utf8');
}

function parseJsonPrefix(text) {
  if (typeof text !== 'string') return null;

  const start = text.search(/[\[{]/);
  if (start === -1) return null;

  const stack = [];
  let inString = false;
  let escape = false;

  for (let index = start; index < text.length; index += 1) {
    const char = text[index];

    if (inString) {
      if (escape) {
        escape = false;
      } else if (char === '\\') {
        escape = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === '{' || char === '[') {
      stack.push(char);
      continue;
    }

    if (char === '}' || char === ']') {
      const expected = char === '}' ? '{' : '[';
      if (!stack.length || stack[stack.length - 1] !== expected) return null;
      stack.pop();
      if (!stack.length) {
        try {
          return JSON.parse(text.slice(start, index + 1));
        } catch {
          return null;
        }
      }
