// Store Cloudflare Images ID
// Combines page data from R2 upload with Cloudflare Images response
// Outputs: pageNumber, pageType, r2Key, cloudflareImageId, cloudflareImageUrl, orderId, imageUrl, ...

const cloudflareResponse = $input.all();

// Get the original page data from upstream nodes
// Prefer the node that carried R2 keys, then fall back gracefully.
let pageData = [];
try {
  pageData = $items('Carry Page Keys Forward1').all();
} catch (e) {
  try {
    pageData = $items('Upload Cover Preview Image to R2 (3A)1').all();
  } catch (e2) {
    console.warn('[Store CF] Could not find upstream nodes, using input data');
    const allItems = $input.all();
    pageData = allItems.map(item => item.json || item);
  }
}

const results = [];
const accountHash = 'JE-pa9WKaCMtKxy6dQQG7A';

for (let i = 0; i < pageData.length; i++) {
  const page = pageData[i] || {};
  const cloudflare = cloudflareResponse[i];

  let cloudflareImageId = null;
  let cloudflareImageUrl = null;

  // Meta from Cloudflare (most reliable)
  let meta = {};
  if (cloudflare && cloudflare.json && cloudflare.json.result && cloudflare.json.result.meta) {
    meta = cloudflare.json.result.meta || {};
  }

  let pageNumberFromMetadata =
    meta.pageNumber !== undefined ? meta.pageNumber :
    meta.pageNum !== undefined ? meta.pageNum :
    null;

  let pageTypeFromMetadata =
    meta.pageType || meta.type || null;

  let orderIdFromMetadata =
    meta.orderId || meta.amazonOrderId || null;

  if (cloudflare && cloudflare.json) {
    console.log(
      `[Cloudflare Images] Item ${i + 1} response:`,
      JSON.stringify(cloudflare.json, null, 2)
    );

    const res = cloudflare.json.result;

    if (res) {
      // Single image
      if (res.id) {
        cloudflareImageId = res.id;
      }
      // Batch-style: result.images[0]
      else if (Array.isArray(res.images) && res.images[0] && res.images[0].id) {
        cloudflareImageId = res.images[0].id;
      }
    }

    if (cloudflareImageId && accountHash) {
      cloudflareImageUrl = `https://imagedelivery.net/${accountHash}/${cloudflareImageId}/public`;
    }

    if (cloudflare.json.errors && cloudflare.json.errors.length > 0) {
      console.error(`[Cloudflare Images] Item ${i + 1} errors:`, cloudflare.json.errors);
    }

    if (cloudflare.json.success === false) {
      console.warn(`[Cloudflare Images] Item ${i + 1} upload failed:`, cloudflare.json);
    }
  } else if (cloudflare && cloudflare.error) {
    console.error(
      `[Cloudflare Images] Item ${i + 1} HTTP error:`,
      cloudflare.error.message || cloudflare.error
    );
  } else {
    console.warn(`[Cloudflare Images] Item ${i + 1} has no response data`);
  }

  // Strip reserved keys like "error"
  const { error, ...pageDataWithoutError } = page;

  // --- Resolve pageNumber (covers + interiors) ---

  let finalPageNumber;

  if (pageNumberFromMetadata !== null && pageNumberFromMetadata !== undefined) {
    // Allow numeric pageNumber, including -1 for cover
    const n = Number(pageNumberFromMetadata);
    finalPageNumber = Number.isNaN(n) ? pageNumberFromMetadata : n;
  } else if (page.pageNumber !== undefined || page.pageNum !== undefined) {
    const n = Number(page.pageNumber ?? page.pageNum);
    finalPageNumber = Number.isNaN(n) ? 0 : n;
  } else if (pageTypeFromMetadata === 'cover-spread' || page.isCover) {
    // Explicit cover fallback
    finalPageNumber = -1;
  } else {
    // Last resort: index
    finalPageNumber = i;
  }

  // --- Resolve orderId ---
  const finalOrderId =
    orderIdFromMetadata ||
    page.orderId ||
    page.amazonOrderId ||
    null;

  // --- Resolve pageType (for clarity) ---
  const finalPageType =
    pageTypeFromMetadata ||
    page.pageType ||
    (finalPageNumber === -1 ? 'cover-spread' : 'interior');

  // --- Resolve r2Key ---
  const r2Key =
    page.pageImageR2Key ||
    page.r2Key ||
    page.coverImageR2Key || // cover spread key support
    page.key ||
    page.fileName ||
    null;

  results.push({
    pageNumber: finalPageNumber,
    pageType: finalPageType,
    r2Key,
    cloudflareImageId,
    cloudflareImageUrl,
    orderId: finalOrderId,
    imageUrl: page.imageUrl || null,
    ...pageDataWithoutError
  });
}

console.log(
  `[Cloudflare Images] Processed ${results.length} items, ${
    results.filter(r => r.cloudflareImageId).length
  } with Cloudflare IDs`
);

return results;

// Keep the binary AND reattach keys needed later
const base = $items('Set Cover PNG Filenames/Keys')?.[0]?.json || {};
return [{
  json: {
    ...$json,
    orderId: base.orderId,
    coverPdfR2Key: base.coverPdfR2Key,
    coverPdfFilename: base.coverPdfFilename,
  },
  // <-- THIS preserves the downloaded file
  binary: $binary
}];

const j = $json || {};
const b = $binary || {};
const itemIx = typeof $itemIndex === 'number' ? $itemIndex : 0;
const backendUrl = String(j.backendUrl || 'https://admin.littleherolabs.com').replace(/\/$/, '');
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: backendUrl + '/api/internal/w3/render-preview-document',
  headers: {
    Authorization: 'Bearer e41d510ce6ed6e9c7f602fea860f2591cc7ec75fe63e448336a97c4b73898646',
    'Content-Type': 'application/json',
  },
  body: {
    ...j,
    documentKind: 'cover-preview',
  },
  json: true,
  timeout: 90000,
});

return {
  json: response && typeof response === 'object' && !Array.isArray(response)
    ? response
    : { response },
  binary: b,
  pairedItem: { item: itemIx },
};

// Store Cloudflare Images ID
// Combines current child-order page data with Cloudflare Images responses.
// Outputs: pageNumber, pageType, r2Key, cloudflareImageId, cloudflareImageUrl, orderId, imageUrl, ...

function safeNodeFirst(name) {
  try {
    return $items(name, 0, $runIndex)?.[0]?.json || {};
  } catch {
    return {};
  }
}

function safeNodeAll(name, runIndex = $runIndex) {
  try {
    return ($items(name, 0, runIndex) || []).map(item => item?.json || item || {});
  } catch {
    return [];
  }
}

function safeNodeAllRuns(name, maxRuns = 12) {
  const items = [];
  const seen = new Set();
  const runIndices = [];

  if (Number.isInteger($runIndex) && $runIndex >= 0) {
    runIndices.push($runIndex);
  }

  for (let i = 0; i < maxRuns; i++) {
    if (!runIndices.includes(i)) {
      runIndices.push(i);
    }
  }

  for (const runIndex of runIndices) {
    for (const entry of safeNodeAll(name, runIndex)) {
      const key = JSON.stringify([
        normalizeId(entry.orderId) || normalizeId(entry.amazonOrderId) || normalizeId(entry.rootOrderId),
        Number(entry.pageNumber ?? extractPageNumber(entry.pageImageFilename || entry.pageImageR2Key || entry.r2Key || entry.fileName || '')),
        entry.pageImageR2Key || entry.r2Key || entry.fileName || entry.result?.id || entry.result?.filename || '',
      ]);

      if (seen.has(key)) {
        continue;
      }
      seen.add(key);
      items.push(entry);
    }
  }

  return items;
}

function normalizeId(value) {
  return value == null ? '' : String(value).trim();
}

function normalizeRootOrderId(value) {
  const id = normalizeId(value);
  return id ? id.replace(/-item-\d+$/, '') : '';
}

function extractPageNumber(value) {
  const match = /p(\d+)\.png$/i.exec(String(value || ''));
  return match ? Number(match[1]) : null;
}

function extractOrderIdFromKey(value) {
  const match = /orders\/([^\/]+)\//.exec(String(value || ''));
  return match ? normalizeId(match[1]) : '';
}

function collectOrderIds(items) {
  const ids = new Set();

  for (const item of items) {
    const data = item?.json || item || {};
    const meta = data.result?.meta || {};
    const candidates = [
      data.orderId,
      meta.orderId,
      data.childOrderId,
      data.amazonOrderId,
      data.rootOrderId,
      data.pageImageR2Key,
      data.r2Key,
      data.manifestKey,
    ];

    for (const candidate of candidates) {
      const id = normalizeId(candidate);
      if (id && !String(candidate).includes('/')) {
        ids.add(id);
      }
    }

    const keyOrderId =
      extractOrderIdFromKey(data.pageImageR2Key) ||
      extractOrderIdFromKey(data.r2Key) ||
      extractOrderIdFromKey(data.manifestKey);
    if (keyOrderId) {
      ids.add(keyOrderId);
    }
  }

  return [...ids];
}

function sortPages(items) {
  return [...items].sort((a, b) => Number(a.pageNumber || 0) - Number(b.pageNumber || 0));
}

const ready = safeNodeFirst('Get Order Ready for Assembly');
const build = safeNodeFirst('Build Assembly Input From Manifest');
const inputItems = ($input.all() || []).map(item => item?.json || item || {});
const inputOrderIds = collectOrderIds(inputItems);

const currentOrderId =
  normalizeId(ready.orderId) ||
  normalizeId(build.orderId) ||
  normalizeId($input.first()?.json?.orderId) ||
  (inputOrderIds.length === 1 ? inputOrderIds[0] : '') ||
  '';
const currentAmazonOrderId =
  normalizeId(ready.amazonOrderId) ||
  normalizeId(build.amazonOrderId) ||
  normalizeId($input.first()?.json?.amazonOrderId) ||
  normalizeId($input.first()?.json?.rootOrderId) ||
  normalizeId(ready.rootOrderId) ||
  normalizeId(build.rootOrderId) ||
  normalizeRootOrderId(currentOrderId) ||
  currentOrderId;
const currentRootOrderId =
  normalizeId(ready.rootOrderId) ||
  normalizeId(build.rootOrderId) ||
  normalizeId($input.first()?.json?.rootOrderId) ||
  normalizeRootOrderId(currentAmazonOrderId) ||
  currentAmazonOrderId;

if (!currentOrderId) {
  throw new Error(
    `Store Cloudflare Images ID1 could not resolve current child orderId. Input orderIds: ${inputOrderIds.join(', ') || 'none'}`
  );
}

const accountHash = 'JE-pa9WKaCMtKxy6dQQG7A';
const cloudflareResponse = inputItems.filter(data => {
  const meta = data.result?.meta || {};
  const responseOrderId =
    normalizeId(meta.orderId) ||
    normalizeId(data.orderId) ||
    normalizeId(data.childOrderId) ||
    extractOrderIdFromKey(data.pageImageR2Key) ||
    extractOrderIdFromKey(data.r2Key) ||
    '';
  return !responseOrderId || responseOrderId === currentOrderId;
});

let pageData = safeNodeAll('Carry Page Keys Forward (PNG)').filter(page => {
  const pageOrderId =
    normalizeId(page.orderId) ||
    normalizeId(page.childOrderId) ||
    extractOrderIdFromKey(page.pageImageR2Key) ||
    extractOrderIdFromKey(page.r2Key) ||
    normalizeId(page.amazonOrderId);
  return pageOrderId === currentOrderId;
});

if (!pageData.length) {
  pageData = safeNodeAllRuns('Carry Page Keys Forward (PNG)').filter(page => {
    const pageOrderId =
      normalizeId(page.orderId) ||
      normalizeId(page.childOrderId) ||
      extractOrderIdFromKey(page.pageImageR2Key) ||
      extractOrderIdFromKey(page.r2Key) ||
      normalizeId(page.amazonOrderId);
    return pageOrderId === currentOrderId;
  });
}

if (!pageData.length) {
  pageData = safeNodeAllRuns('Upload Page Preview Image to R2').filter(page => {
    const pageOrderId =
      normalizeId(page.orderId) ||
      normalizeId(page.childOrderId) ||
      extractOrderIdFromKey(page.pageImageR2Key) ||
      extractOrderIdFromKey(page.r2Key) ||
      normalizeId(page.amazonOrderId);
    return pageOrderId === currentOrderId;
  });
}

if (!pageData.length) {
  console.warn('[Store Cloudflare Images ID1] Rebuilding page data from Cloudflare response metadata');
  pageData = cloudflareResponse
    .map((data, index) => {
      const meta = data.result?.meta || {};
      const pageNumber = Number(meta.pageNumber ?? data.pageNumber);
      const fileName = data.result?.filename || data.filename || `p${String(index).padStart(2, '0')}.png`;
      if (!Number.isFinite(pageNumber)) {
        return null;
      }
      return {
        orderId: currentOrderId,
        amazonOrderId: currentAmazonOrderId,
        rootOrderId: currentRootOrderId,
        pageNumber,
        pageType: 'interior',
        pageImageFilename: fileName,
        pageImageR2Key: `book-mvp-simple-adventure/orders/${currentOrderId}/preview-images/${fileName}`,
        r2Key: `book-mvp-simple-adventure/orders/${currentOrderId}/preview-images/${fileName}`,
        imageUrl: null,
      };
    })
    .filter(Boolean);
}

pageData = sortPages(pageData);

const responsesByPage = new Map();
for (const data of cloudflareResponse) {
  const meta = data.result?.meta || {};

  let pageNumber = Number(meta.pageNumber ?? data.pageNumber);
  if (!Number.isFinite(pageNumber)) {
    pageNumber = extractPageNumber(data.result?.filename || data.filename || data.pageImageFilename || '');
  }
  if (!Number.isFinite(pageNumber)) {
    continue;
  }

  let cloudflareImageId =
    data.cloudflareImageId ||
    data.result?.id ||
    (Array.isArray(data.result?.images) ? data.result.images[0]?.id : null) ||
    null;
  let cloudflareImageUrl = data.cloudflareImageUrl || null;

  if (!cloudflareImageUrl && cloudflareImageId) {
    cloudflareImageUrl = `https://imagedelivery.net/${accountHash}/${cloudflareImageId}/public`;
  }
  if (!cloudflareImageUrl && Array.isArray(data.result?.variants) && data.result.variants.length > 0) {
    cloudflareImageUrl = data.result.variants[0] || data.result.variants[1] || null;
  }

  responsesByPage.set(pageNumber, {
    cloudflareImageId,
    cloudflareImageUrl,
  });
}

const results = pageData.map((page, index) => {
