function parseJson(value) {
  if (!value || typeof value !== 'string') return null;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function filenameToPageNumber(fileName) {
  const match = /p(\d+)\.png$/i.exec(String(fileName || ''));
  return match ? Number(match[1]) : null;
}

